    "description": "\"A legendary warlock of the Moniyan Empire, surrounded by myriad riddles and mystique. It's said that he is truly omniscient, and that he recorded his boundless knowledge in note form.\" (Skin Overview)",
    "story": "\"A legendary warlock of the Moniyan Empire, surrounded by myriad riddles and mystique. It's said that he is truly omniscient, and that he recorded his boundless knowledge in note form.\" (Skin Overview)",
