        "tier": "Passive",
        "types": [
          "Buff"
        ],
        "description": "When an enemy uses its Ultimate, an effect is triggered depending on the target's Type that lasts for 4s. 15px Elemental: Heal all allies equal to 50% of Akashic's Attack every 2s. 15px Martial: Grant each front row ally a Shield equal to 150% of Akashic's Attack. 15px Tech: Increase all allies' Crit Rate by 6%. 15px Light: Have all allied heroes recover 80 Energy. 15px Dark: Increase all allies' Lifesteal by 30. 15px Order: Increase all allies' Damage Reduction by 6%. 15px Chaos: Increase all allies' Damage Increase by 6%.",
