    "id": "beatrice",
    "name": "Beatrice",
    "type": "Astral",
    "rarity": "SSR",
    "class": "Support",
    "advancedClass": "Spirit",
    "equipmentSize": "Medium",
    "description": "Beatrice is an Astral hero from Mobile Legends: Adventure, released on with a dedicated Tinted Mirage event.",
    "story": "Beatrice is an Astral hero from Mobile Legends: Adventure, released on with a dedicated Tinted Mirage event.",
    "faction": "Astral",
    "subFactions": [],
    "capabilities": "",
    "abilities": [
      {
        "name": "Blood Bargain",
        "tier": "Ultimate",
        "types": [
          "Shield",
          "Buff"
        ],
        "description": "Grants all allied heroes a Shield equal to 10% of their Max HP. Allied Heroes with more than 40% Max HP lose 35% of their current HP and gain an additional Shield equal to 30% of their Max HP, lasting 12s. Meanwhile, enhances all allied heroes, causing them to deal increased damage to enemies when their HP percentage is lower, reaching a maximum of 60% increased damage when HP is at 50%. Converts all HP regen effects to Shields at a 100% ratio, capped at 200% of the hero's Max HP, lasting 12s. Shield persists after the enhancement ends.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "Dispels targets' received healing reduction and Shield reduction effects before granting a Shield. While the effect lasts, allied heroes with Shield gain 70% Damage-triggered Energy Regen when taking damage."
          },
          {
            "level": "3",
            "text": "Increases all allied heroes' Shield gained to 15% of Max HP."
          },
          {
            "level": "4",
            "text": "Increases all allied heroes' Shield gained to 20% of Max HP. (Requires Ancient Twilight Level 3)"
          }
        ]
      },
      {
        "name": "Enchanted Grace",
        "tier": "Skill",
        "types": [
          "Buff",
          "Heal"
        ],
        "description": "Heals 2 allied heroes with the lowest HP percentage for 120% of Beatrice's Attack, and restores 15 Energy per second for 4s.This skill affects all other allied heroes with HP percentage lower than or equal to 60%.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "The healing is increased to 160%."
          },
          {
            "level": "3",
            "text": "When allied heroes receive healing from other Astral heroes, both the hero and the healer restore 30 Energy. Can only trigger once evert 4s."
          },
          {
            "level": "4",
            "text": "The healing is increased to 200%."
          }
        ]
      },
      {
        "name": "Enchanted Trick",
        "tier": "Skill",
        "types": [
          "Buff"
        ],
        "description": "Targets 2 other allied heroes with the fewest Enchanted Trick stacks, reducing their Defense by 40% but granting them 1 stack of Enchanted Trick. Enemy heroes reduce Enchanted Trick stacks by 1 every 5 cast(s) of Ultimate. Enchanted Trick:1 or more stacks: Energy acquisition efficiency increases by 4%2 or more stacks: Damage dealt and healing increase by 10%3 or more stacks: Attack increases by 10%, Agility increases by 50This skill won't be used when all other allied heroes have 3 stacks of Enchanted Trick.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "Allied heroes with HP at or below 60% and Astral Heroes gain 2 stacks of Enchanted Trick each time."
          },
          {
            "level": "3",
            "text": "Increases Energy acquisition efficiency to 8%."
          },
          {
            "level": "4",
            "text": "Increases Energy acquisition efficiency to 12%. (Requires Ancient Twilight Level 1)"
          }
        ]
      },
      {
        "name": "Benevolent Elder",
        "tier": "Passive",
        "types": [
          "Buff"
        ],
        "description": "When allied heroes' HP drops below 30%, they can cast their Ultimate once without consuming Energy every 40s. Additionally, when their HP first drops below 30%, they remove most control and target-changing effects and gain 10 Lifesteal for the rest of the battle.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "When Beatrice's HP drops below 75%, becomes immune to control and target-changing effects."
          },
          {
            "level": "3",
            "text": "Increases Lifesteal gained to 15."
          },
          {
            "level": "4",
            "text": "Increases Lifesteal gained to 20. (Requires Ancient Twilight Level 2)"
          }
        ]
      }
    ],
    "title": "Eternal Enchantress",
    "releaseDate": "September 19",
    "releaseYear": "2025",
