    "advancedClass": "Inquisitor",
    "equipmentSize": "Heavy",
    "description": "(In-game Info) After Silvanna's father fell ill, she took over as the ruler of the Moniyan Empire. However, the weight of her new responsibility lef her lost and confused, unsure of what the future held. When caught in a web of intrigue, it can be difficult to know what you truly want. Silvanna was no exception. As she began to navigate the unfamiliar world of politics and deal with outspoken officials, she had to find her own way of doing things. But as we know, Silvanna is a fighter. A moment of confusion won't make her give up or lose faith. When the empire is faced with internal and external crises, Silvanna will always be at the forefront, leading of charge. \"I am the very symbol of Moniyan,\" Silvanna declared. Her promise to protect her country is a commitment that can never be broken. With the flag held high in her hand, she will defend Moniyan until the end of time.",
    "story": "(In-game Info) After Silvanna's father fell ill, she took over as the ruler of the Moniyan Empire. However, the weight of her new responsibility lef her lost and confused, unsure of what the future held. When caught in a web of intrigue, it can be difficult to know what you truly want. Silvanna was no exception. As she began to navigate the unfamiliar world of politics and deal with outspoken officials, she had to find her own way of doing things. But as we know, Silvanna is a fighter. A moment of confusion won't make her give up or lose faith. When the empire is faced with internal and external crises, Silvanna will always be at the forefront, leading of charge. \"I am the very symbol of Moniyan,\" Silvanna declared. Her promise to protect her country is a commitment that can never be broken. With the flag held high in her hand, she will defend Moniyan until the end of time.",
