    "story": "\"Praised be her sacred name — the primordial universe, Goddess of the Stars, Mother of Dragons, the Eternal Cradle, the Primordial Star — Sharana. This is no mere legend; she is the very essence of legend itself. We are born from her blood, slumbering within her boundless dreams.\" Skin overview",
