        "types": [
          "Buff",
          "Control"
        ],
        "description": "Passive: Genesis Shar summons the Goldblaze Dragon with the ability to release a bind to a random enemy that penetrates control immunity every 4s when the battle begins. The bound enemy will be unable to gain Damage-triggered Energy Regen for 2s . When used actively, she enhances herself and the Goldblaze Dragon. The Goldblaze Dragon immediately refreshes the duration of the current bind, all enemies are forced to attack the bound target for 3s. An instant bind activates on a random enemy when there are no bound targets. Genesis Shar's Basic Attack becomes Golden Resonance with an increased area of effect for 5s.",
