          {
            "level": "3",
            "text": "This skill deals a minimum amount of damage equal to 460% of Guinevere's Attack."
          },
          {
            "level": "4",
            "text": "This skill deals a minimum amount of damage equal to 600% of Guinevere's Attack. (Requires Ancient Twilight Level 3)"
          }
