        "tier": "Skill",
        "types": [
          "Control"
        ],
        "description": "Guinevere uses anti-gravity magic to trigger an explosion that deals damage equal to 150% of her Attack to enemies in the area and knocks them airbourne. In the next 3s, Guinevere continues to deal damage equal to 40% of her Attack to them.",
