    "capabilities": "A Mage who deals AoE damage and provides buffs. Her Ultimate also restores Energy for allies. Her Realm Skill allows an ally to instantly cast their Ultimate again.",
    "abilities": [
      {
        "name": "Primordial Protocol",
        "tier": "Ultimate",
        "types": [
          "Buff",
          "AoE"
        ],
        "description": "Heartcore Angela briefly becomes untargetable and releases an energy orb at the enemy who has dealt the most cumulative damage. The orb bounces 5 times between this enemy and the allied hero who has dealt the most cumulative damage. When the energy orb hits enemies, it deals damage equal to 100% of Heartcore Angela's Attack plus 8% of the enemy's Max HP to nearby enemies. The Max HP damage won't exceed 800% of Heartcore Angela's Attack. When the energy orb hits an allied hero, it removes most control and target-changing effects from that hero and restores 100 Energy to them.Passive: Heartcore Angela's Max Energy is 8. She gains 1 Energy when she uses Algorithm Lock or Love's Vengeance. Her Energy is not affected by other effects.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "When Heartcore Angela gains Energy through means other than Algorithm Lock and Love's Vengeance, she converts every 100 Energy gained into 10% Attack, up to a maximum of 100% Attack."
          },
          {
            "level": "3",
            "text": "Damage dealt is increased to 110%."
          },
          {
            "level": "4",
            "text": "Damage dealt is increased to 120%. (Requires Ancient Twilight Level 3)"
          }
        ]
      },
      {
        "name": "Algorithm Lock",
        "tier": "Skill",
        "types": [
          "Debuff",
          "AoE"
        ],
        "description": "Heartcore Angela commands Darkheart Doll to deal damage equal to 70% of her Attack to the 3 farthest enemy heroes and marks them for 6s. Marked enemies take 15% increased damage during this period, while allied heroes take 20% less damage from unmarked units.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "Damage dealt is increased to 85%."
          },
          {
            "level": "3",
            "text": "Heartcore Angela gain 2 Initial Energy."
          },
          {
            "level": "4",
            "text": "Damage dealt is increased to 100%."
          }
        ]
      },
      {
        "name": "Love's Vengeance",
        "tier": "Skill",
        "types": [
          "Damage"
        ],
        "description": "Heartcore Angela causes an enemy to take damage equal to 2% of their Max HP per second until the end of the battle, capped at 200% of Heartcore Angela's Attack. This effect can stack up to 5 times. Prioritizes enemies not affected by this effect. When an enemy affected by this skill dies, Heartcore Angela gains 1 Energy.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "The damage dealt when first hitting an enemy is eual to 100% of Attack."
          },
          {
            "level": "3",
            "text": "Damage dealt is increases to 2.5%, capped at 250% of Heartcore Angela's Attack."
          },
          {
            "level": "4",
            "text": "Damage dealt is increases to 3%, capped at 300% of Heartcore Angela's Attack. (Requires Ancient Twilight Level 1)"
          }
        ]
      },
      {
        "name": "Neural Override",
        "tier": "Passive",
        "types": [
          "Buff"
        ],
        "description": "Every 10s, if Heartcore Angela's Max Energy is 7 or higher, she converts 1 Max Energy into 1 Energy Source. Each Energy Source increases her Ultimate's ricochet count by 1.When Heartcore Angela's HP drops below 65%, if her Max Energy is 6 or higher, she reduces her Max Energy by 1, removes most Control effects and HP Regen restrictions (including Healing Reduction, Health Block, nd HP Regen-to-Shield conversion), recovers all lost HP, immediately triggers her Ultimate's effect, and resets the Energy conversion timer.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "When Max Energy is reduced to 6, Heartcore Angela gains 5% Crit Rate."
          },
          {
            "level": "3",
            "text": "When Max Energy is reduced to 6, Heartcore Angela gains 10% Crit Rate."
          },
          {
            "level": "4",
            "text": "When Max Energy is reduced to 6, Heartcore Angela gains 15% Crit Rate. (Requires Ancient Twilight Level 2)"
          }
        ]
      },
      {
        "name": "Code Domain",
        "tier": "Realm Effect",
        "types": [],
        "description": "At the start of the battle, selects 1 allied hero (can select Heartcore Angela herself). After this hero actively casts their Ultimate, they can cast their Ultimate once more without Energy cost. This can be triggered once every 12s. When this hero dies, immediately selects another allied hero to gain this effect.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "[All HP Boost] All allies in the same team gain HP +3%. (Unlocks at 32px)"
          },
          {
            "level": "3",
            "text": "At the start of the battle, selects 1 allied hero. After this hero actively casts their Ultimate, they can cast their Ultimate once more without Energy cost. This can be triggered once every 12s. When this hero dies, immediately selects another allied hero to gain this effect. (Unlocks at 32px)"
          },
          {
            "level": "4",
            "text": "When this hero casts their Ultimate, all other allied heroes recover 50 Energy. (Unlocks at 64px)"
          },
          {
            "level": "5",
            "text": "[All Attack Boost] All allies in the same team gain Attack +3%. (Unlocks at 80px)"
          },
          {
            "level": "6",
            "text": "When this hero casts their Ultimate, all other allied heroes recover 100 Energy. (Unlocks at 16px)"
          }
        ]
      }
    ],
