        "description": "Every time Mecha Layla deals damage equal to 1000% of her Attack, her Power Level will increase by 1. Different Power Levels grant different effects: Power Level 1: Intermittently unleashes a healing wave to heal all allies by an amount of HP equal to 2.5% of her Max HP. Power Level 2: Increases the damage of Laser Domain by 100%. Power Level 3: Greatly increases the frequency of projectiles.",
