        "description": "Deals damage equal to 200% of her Attack to all enemies and makes Nonas enraged. For the next 10s, Nonas steal 50% more HP when fighting and gains 100% more HP Regen when resting. Passive: At the beginning of the battle, both Nonas are granted 25% of Morpheus' Max HP and float around her, resting and untargetable. Nonas are immune to Control effects; if they are about to be defeated, they will return to rest and recover 10% Max HP per second.",
