        "description": "Natan shoots 5 arrows of light to attack random enemies, each dealing damage equal to 105% of his Attack. Arrows stay on the target after hitting it, and each enemy unit can have no more than 3 arrows attached to it. When Shadow of Future uses this skill, it recalls all the arrows of light that are staying on enemies, each recalled arrow dealing damage equal to 15% of its target's lost HP to the target.",
