        "description": "Natan attacks the nearest enemy, dealing damage equal to 300% of his Attack and adding a spacetime mark to it that lasts for 6s. The marked target cannot receive the regen effects of energy and HP. When Shadow of Future uses this skill, it drags enemy units that don't have as spacetime mark out of the battlefield, lasting for 4s. These units cannot move and only take damage from Shadow of Future within the duration.",
