    "description": "At the south of the Monian Empire, a bottomless abyss is carved into the desert landscape. The locals call this place the Abyss of Shadows. Few know that deep within the Dark Abyss, the most terrifying demon of the Dawn Earth is sealed — the Lord of the Abyss. Over the centuries, the seal of the Abyss has slowly faded, giving way to the ravenous will of the Abyss. The demons strengthened their control over the darkness. Many fanatics offered sacrifices to the Abyss, unknowingly feeding the demons formed from dark energy, always hiding within the shadows. Selena, a young dark elf, was offered to them as a sacrifice in exchange for dark energy. The Abyss Demon filled Selena with despair and pain, piercing every cell of her body. Just as Selena was nearly consumed by darkness, a miracle occurred. A mysterious warm blue light enveloped her and seemed to struggle with the dark abyss for control over her body. When Selena awoke, she found herself still lying in the Abyss, but her skin now emitted a strange blue glow, and her once lavender eyes were filled with a majestic crimson radiance — the Abyss Demon was resting inside her. Then the Will of the Abyss spoke: This girl is deeply loved, and that love protected her from being consumed by darkness. The Abyss and the Moon God, two opposing forces, have reached balance within her body. An ancient and deep voice echoed in the minds of the demons: Leave this girl to me. She will become the strongest warrior of the Abyss! The demons obeyed the command and left Selena. She forgot her past, but quickly discovered that she could manipulate the dark magic of the Abyss. She could absorb the power of the Abyss into her body to transform into a demoness capable of tearing enemies apart. The Will of the Abyss echoed in her voice, granting Selena unquestionable authority over the Abyss demons. Even Alice, the proud Queen of Blood Magic, felt uncertain when she looked at the dark young elf — not only because Alice could sense the terrifying power lying within this seemingly cute and mischievous girl named Selena.",
    "story": "At the south of the Monian Empire, a bottomless abyss is carved into the desert landscape. The locals call this place the Abyss of Shadows. Few know that deep within the Dark Abyss, the most terrifying demon of the Dawn Earth is sealed — the Lord of the Abyss. Over the centuries, the seal of the Abyss has slowly faded, giving way to the ravenous will of the Abyss. The demons strengthened their control over the darkness. Many fanatics offered sacrifices to the Abyss, unknowingly feeding the demons formed from dark energy, always hiding within the shadows. Selena, a young dark elf, was offered to them as a sacrifice in exchange for dark energy. The Abyss Demon filled Selena with despair and pain, piercing every cell of her body. Just as Selena was nearly consumed by darkness, a miracle occurred. A mysterious warm blue light enveloped her and seemed to struggle with the dark abyss for control over her body. When Selena awoke, she found herself still lying in the Abyss, but her skin now emitted a strange blue glow, and her once lavender eyes were filled with a majestic crimson radiance — the Abyss Demon was resting inside her. Then the Will of the Abyss spoke: This girl is deeply loved, and that love protected her from being consumed by darkness. The Abyss and the Moon God, two opposing forces, have reached balance within her body. An ancient and deep voice echoed in the minds of the demons: Leave this girl to me. She will become the strongest warrior of the Abyss! The demons obeyed the command and left Selena. She forgot her past, but quickly discovered that she could manipulate the dark magic of the Abyss. She could absorb the power of the Abyss into her body to transform into a demoness capable of tearing enemies apart. The Will of the Abyss echoed in her voice, granting Selena unquestionable authority over the Abyss demons. Even Alice, the proud Queen of Blood Magic, felt uncertain when she looked at the dark young elf — not only because Alice could sense the terrifying power lying within this seemingly cute and mischievous girl named Selena.",
