        "description": "Charm 2 random enemy units for 6s. While charmed, they take damage equal to 150% of her Attack per second, and gain an Abyssal Mark. Casting this a second time switches her into Abyssal Form, greatly increasing Selena's Agility and Lifesteal. Selena's Ultimate now deals AoE Damage, inflicting Abyssal Marks on those damaged.",
