    "description": "(in-game Info) Through the Energy Channel of the dream world, Lunox seized the transcendent might of Order and Chaos, ascending to the pinnacle of power. As challenges loomed amidst the enigmatic haze of the Land of Dawn's uncertain destiny, she pressed forward, unyielding and relentless. With unwavering resolve, she invokes the Twilight Orb's potential, shattering the veils of illusion. Through the shroud of deception, she embraced the veritable truth, becoming the harbinger of eternity within the domain of the Twilight Orb.",
    "story": "(in-game Info) Through the Energy Channel of the dream world, Lunox seized the transcendent might of Order and Chaos, ascending to the pinnacle of power. As challenges loomed amidst the enigmatic haze of the Land of Dawn's uncertain destiny, she pressed forward, unyielding and relentless. With unwavering resolve, she invokes the Twilight Orb's potential, shattering the veils of illusion. Through the shroud of deception, she embraced the veritable truth, becoming the harbinger of eternity within the domain of the Twilight Orb.",
    "faction": "Hybrid",
    "subFactions": [
      "Order",
      "Chaos"
    ],
    "capabilities": "Powerfull all-rounder support, capable of healing, enhancing, reviving allies, and also dealing damage.",
    "abilities": [
      {
        "name": "Dusk Till Dawn",
        "tier": "Ultimate",
        "types": [
          "Debuff",
          "Buff"
        ],
        "description": "Losing 40% of her current HP, Singularity Lunox gains a shield equal to 40% of her Max HP and unleashes Twilight Cosmos for 6s. When the Twilight Cosmos is active, allied units deal 20% more damage, and enemy units deal 20% less damage.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "Within the Twilight Cosmos, allies whose HP is above 80% remove and become immune to most control effects, while enemies whose HP is above 80% receive 30% less healing."
          },
          {
            "level": "3",
            "text": "During the skill duration, allies deal an extra 25% damage."
          },
          {
            "level": "4",
            "text": "During the skill duration, allies deal an extra 30% damage. (Requires Ancient Twilight Level 3)"
          }
        ]
      },
      {
        "name": "Singularity Pulse",
        "tier": "Skill",
        "types": [
          "Buff",
          "AoE"
        ],
        "description": "Teleports to the location with the most enemies, dealing damage equal to 100% of Attack to nearby enemies.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "Damage is increased to 110% of Attack."
          },
          {
            "level": "3",
            "text": "Every time she casts Singularity Pulse, her basic attacks gain an extra 10% Lifesteal, stacking up to 3 times."
          },
          {
            "level": "4",
            "text": "Damage is increased to 120% of Attack."
          }
        ]
      },
      {
        "name": "Starfall Strike",
        "tier": "Skill",
        "types": [
          "Debuff",
          "AoE"
        ],
        "description": "Unleashes Starfall Strike, dealing damage equal to 30% of Attack to targets in the range 3 times.Additionally, each time deals extra damage equal to 5% of the target's Max HP (cannot exceed 500% of her Attack). This skill also grants an extra 10% Lifesteal.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "Each time dealing damage, reduces the targets' received healing and shields by 5%, up to 60%."
          },
          {
            "level": "3",
            "text": "Damage is increased to 35% of Attack."
          },
          {
            "level": "4",
            "text": "Damage is increased to 40% of Attack. (Requires Ancient Twilight Level 1)"
          }
        ]
      },
      {
        "name": "Call of Fate",
        "tier": "Passive",
        "types": [
          "Debuff",
          "Buff",
          "Heal"
        ],
        "description": "For every 10% of Singularity Lunox's HP lost, she heals all allies for an amount of HP equal to 70% of her Attacks.While in the Twilight's Dawn form, every second she deals damage equal to 20% of Attack to nearby enemies and absorbs 0.5% of their Attack.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "For allies whose HP is below 50%, the healing effect of the Call of Fate is increased by 50%.While in the Twilight Dawn form, Singularity Lunox reduces the Energy of nearby enemies by 10 per second and converts 50% of it into her own Energy"
          },
          {
            "level": "3",
            "text": "The healing is increased to 80% of Attack."
          },
          {
            "level": "4",
            "text": "The healing is increased to 90% of Attack. (Requires Ancient Twilight Level 2)"
          }
        ]
      },
      {
        "name": "Singularity Domain",
        "tier": "Realm Effect",
        "types": [],
        "description": "Whenever an ally dies, they leave behind a small amount of Twilight Power, enabling them to revive with 30% HP at their original location in 10s. Each time an ally is revived by this effect, their next revival time will be doubled. Allies revived by any effect will receive 50% less healing and shields.",
        "levelDescriptions": [
          {
            "level": "2",
            "text": "[All HP Boost] All allies in the same team gain HP +3%. (Unlocks at 32px)"
          },
          {
            "level": "3",
            "text": "Allied heroes revive with 45% HP. (Unlocks at 48px)"
          },
          {
            "level": "4",
            "text": "Allied heroes revive with 60% HP. (Unlocks at 64px)"
          },
          {
            "level": "5",
            "text": "[All Attack Boost] All allies in the same team gain Attack +3%. (Unlocks at 80px)"
          },
          {
            "level": "6",
            "text": "The initial revival time for each ally is reduced to 5s. (Unlocks at 16px)"
          }
        ]
      }
    ],
